draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
var cy = H * 0.48;
var lx = W * 0.18, rx = W * 0.72;
var rad = H * 0.20;

// solenoid body
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(lx, cy - rad); ctx.lineTo(rx, cy - rad); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, cy + rad); ctx.lineTo(rx, cy + rad); ctx.stroke();

// turns
var N = 12;
ctx.strokeStyle = C.figure;
for (var k = 0; k < N; k++) {
  var x = lx + (rx - lx) * (k + 0.5) / N;
  ctx.beginPath();
  ctx.ellipse(x, cy, (rx - lx) / (N * 3.2), rad, 0, 0, Math.PI * 2);
  ctx.stroke();
}

// field lines inside
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
for (var j = -1; j <= 1; j++) {
  var y = cy + j * rad * 0.45;
  ctx.beginPath(); ctx.moveTo(lx + 6, y); ctx.lineTo(rx - 6, y); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(rx - 6, y); ctx.lineTo(rx - 15, y - 4); ctx.lineTo(rx - 15, y + 4);
  ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
}
ctx.lineWidth = 1;

// length marker
ctx.strokeStyle = C.faint;
var ly = cy + rad + 22;
ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(rx, ly); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, cy + rad); ctx.lineTo(lx, ly + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx, cy + rad); ctx.lineTo(rx, ly + 4); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("length l, with N turns (n = N/l per metre)", lx, ly + 16);
ctx.fillStyle = C.accent;
ctx.fillText("B = mu0 n I inside, nearly zero outside", lx + 4, cy - rad - 10);
ctx.fillStyle = C.ink;
ctx.fillText("area A", rx + 8, cy - 4);
ctx.fillText("flux per turn = B A", rx + 8, cy + 14);

// the chain of reasoning
ctx.fillStyle = C.figure;
ctx.fillText("N (B A) = L I   so   L = mu0 n^2 A l", lx, H - 8);

out.note = "Inductance is pure geometry: turns, area and length only. No current appears in L.";

var Lh = p.L, R = p.R, V = p.V;
var tau = Lh / R, Ifin = V / R;
var pad = 42, padR = 16, padT = 18, padB = 30;
var x0 = pad, x1 = W - padR, y0 = padT, y1 = H - padB;
var tMax = 5 * tau;
var X = function (s) { return x0 + (s / tMax) * (x1 - x0); };
var Y = function (i) { return y1 - (i / (Ifin * 1.15)) * (y1 - y0); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, y1); ctx.lineTo(x1, y1); ctx.stroke();

ctx.setLineDash([4, 4]);
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(x0, Y(Ifin)); ctx.lineTo(x1, Y(Ifin)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(tau), y1); ctx.lineTo(X(tau), Y(Ifin)); ctx.stroke();
ctx.setLineDash([]);

// initial slope V/L, the tangent at the origin
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(tau), Y(Ifin));
ctx.stroke();

// the exponential rise
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 160; k++) {
  var s = tMax * k / 160;
  var i = Ifin * (1 - Math.exp(-s / tau));
  if (k === 0) { ctx.moveTo(X(s), Y(i)); } else { ctx.lineTo(X(s), Y(i)); }
}
ctx.stroke();

// sweeping marker
var cyc = t % (tMax * 1.25);
var now = Math.min(cyc, tMax);
var inow = Ifin * (1 - Math.exp(-now / tau));
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
for (var m = 0; m <= 160; m++) {
  var s2 = now * m / 160;
  var i2 = Ifin * (1 - Math.exp(-s2 / tau));
  if (m === 0) { ctx.moveTo(X(s2), Y(i2)); } else { ctx.lineTo(X(s2), Y(i2)); }
}
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(now), Y(inow), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("current I (A)", x0 - 34, y0 - 5);
ctx.fillText("time t (s)", x1 - 54, y1 + 20);
ctx.fillText(Ifin.toFixed(2) + " A = V/R", x1 - 96, Y(Ifin) - 6);
ctx.fillText("t = tau", X(tau) + 4, y1 + 14);
ctx.fillStyle = C.figure;
ctx.fillText("slope V/L", X(tau * 0.45) + 6, Y(Ifin * 0.62));
ctx.fillStyle = C.ink;
ctx.fillText("0", x0 - 10, y1 + 14);

out.note = "tau = L/R = " + tau.toFixed(4) + " s, final current " + Ifin.toFixed(3)
  + " A, stored energy at the end " + (0.5 * Lh * Ifin * Ifin).toFixed(3) + " J. Now I = "
  + inow.toFixed(3) + " A (" + (100 * inow / Ifin).toFixed(1) + "% of final).";

var Lh = p.L * 1e-3, Cf = p.C * 1e-6, Q0 = p.Q * 1e-6;
var w = 1 / Math.sqrt(Lh * Cf);
var T = 2 * Math.PI / w;
var Imax = w * Q0;
var U = Q0 * Q0 / (2 * Cf);

var ang = 2 * Math.PI * t / 4;   // one cycle every 4 s on screen, slowed right down
var q = Q0 * Math.cos(ang);
var i = -Imax * Math.sin(ang);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

// circuit: capacitor left, inductor right
var bx = W * 0.10, bw = W * 0.42, by = H * 0.18, bh = H * 0.44;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(bx, by + bh * 0.5 - 10); ctx.lineTo(bx, by); ctx.lineTo(bx + bw, by);
ctx.lineTo(bx + bw, by + bh); ctx.lineTo(bx, by + bh); ctx.lineTo(bx, by + bh * 0.5 + 10);
ctx.stroke();

// capacitor plates
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(bx - 14, by + bh * 0.5 - 10); ctx.lineTo(bx + 14, by + bh * 0.5 - 10); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 14, by + bh * 0.5 + 10); ctx.lineTo(bx + 14, by + bh * 0.5 + 10); ctx.stroke();
ctx.lineWidth = 1.5;

// inductor coil on the right side
ctx.strokeStyle = C.figure;
var iy = by + bh * 0.5;
for (var k = 0; k < 4; k++) {
  ctx.beginPath();
  ctx.arc(bx + bw, iy - 24 + k * 16, 8, -Math.PI / 2, Math.PI / 2);
  ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.fillText("C", bx - 30, by + bh * 0.5 + 4);
ctx.fillText("L", bx + bw + 14, iy + 4);

// charge sign and current arrow
ctx.fillStyle = C.accent;
ctx.fillText(q >= 0 ? "+q" : "-q", bx - 32, by + bh * 0.5 - 16);
ctx.fillStyle = C.figure;
ctx.fillText(i >= 0 ? "current ->" : "current <-", bx + bw * 0.25, by - 8);

// energy bars
var gx = W * 0.62, gw = W * 0.30, gy = by, gh = bh;
var uE = q * q / (2 * Cf), uB = 0.5 * Lh * i * i;
ctx.fillStyle = C.accent;
ctx.fillRect(gx, gy + gh * (1 - uE / U), gw * 0.38, gh * (uE / U));
ctx.fillStyle = C.figure;
ctx.fillRect(gx + gw * 0.52, gy + gh * (1 - uB / U), gw * 0.38, gh * (uB / U));
ctx.strokeStyle = C.rule;
ctx.strokeRect(gx, gy, gw * 0.38, gh);
ctx.strokeRect(gx + gw * 0.52, gy, gw * 0.38, gh);
ctx.fillStyle = C.ink;
ctx.fillText("electric", gx - 2, gy + gh + 14);
ctx.fillText("magnetic", gx + gw * 0.50, gy + gh + 14);
ctx.fillText("energy shuttles, total fixed", gx - 2, gy - 6);

out.note = "f = " + (1 / T).toFixed(1) + " Hz, T = " + (T * 1000).toFixed(3)
  + " ms, peak current = omega Q0 = " + Imax.toFixed(4) + " A. Right now q = "
  + (q * 1e6).toFixed(2) + " uC and I = " + i.toFixed(4) + " A.";
